<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ChevronDown, ChevronUp, Plus, Save, Trash2 } from 'lucide-vue-next'
import AdminPageHeader from '../../components/admin/AdminPageHeader.vue'
import AdminState from '../../components/admin/AdminState.vue'
import ConfirmModal from '../../components/admin/ConfirmModal.vue'
import { createCategory, deleteCategory, getAdminCourses, getCategories, getSettings, updateSettings } from '../../services/adminApi'

const loading = ref(true); const saving = ref(false); const error = ref(''); const success = ref(''); const categories = ref([]); const courses = ref([]); const categoryName = ref(''); const categorySlug = ref(''); const selectedCategory = ref(null); const deleting = ref(false); const faqOpen = ref(true)
const form = reactive({ contact: { whatsapp_number: '', default_message: '' }, social_links: {}, institutional: {}, global_faq: [], featured_course_ids: [] })
function slugify(value) { return value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') }
function addFaq() { form.global_faq.push({ question: '', answer: '' }) }
function removeFaq(index) { form.global_faq.splice(index, 1) }
async function load() { loading.value = true; try { const [settingsPayload, categoryPayload, coursePayload] = await Promise.all([getSettings(), getCategories(), getAdminCourses({ per_page: 50, sort: 'sort_order', direction: 'asc' })]); Object.assign(form, { contact: settingsPayload.settings.contact || { whatsapp_number: '', default_message: '' }, social_links: settingsPayload.settings.social_links || {}, institutional: settingsPayload.settings.institutional || {}, global_faq: settingsPayload.settings.global_faq || [], featured_course_ids: settingsPayload.featured_course_ids || [] }); categories.value = categoryPayload.data; courses.value = coursePayload.data } catch (requestError) { error.value = requestError.message } finally { loading.value = false } }
async function save() { saving.value = true; error.value = ''; success.value = ''; try { await updateSettings({ settings: { contact: form.contact, social_links: form.social_links, institutional: form.institutional, global_faq: form.global_faq }, featured_course_ids: form.featured_course_ids }); success.value = 'Configurações salvas com sucesso.' } catch (requestError) { error.value = requestError.message } finally { saving.value = false } }
async function addCategory() { if (!categoryName.value) return; try { await createCategory({ name: categoryName.value, slug: categorySlug.value || slugify(categoryName.value), sort_order: categories.value.length + 1 }); categoryName.value = ''; categorySlug.value = ''; categories.value = (await getCategories()).data } catch (requestError) { error.value = requestError.message } }
async function removeCategory() { if (!selectedCategory.value) return; deleting.value = true; try { await deleteCategory(selectedCategory.value.id); selectedCategory.value = null; categories.value = (await getCategories()).data } catch (requestError) { error.value = requestError.message } finally { deleting.value = false } }
onMounted(load)
</script>

<template><AdminPageHeader title="Configurações" description="Dados institucionais e itens que aparecem em todo o site."><template #actions><button class="admin-button primary" type="button" :disabled="saving" @click="save"><Save :size="18" />{{ saving ? 'Salvando…' : 'Salvar alterações' }}</button></template></AdminPageHeader><AdminState v-if="loading" message="Carregando configurações…" /><form v-else class="settings-form" @submit.prevent="save"><p v-if="error" class="form-alert error">{{ error }}</p><p v-if="success" class="form-alert success">{{ success }}</p><section class="form-card"><div class="form-card-heading"><div><h2>Atendimento</h2><p>Informações usadas nos CTAs e mensagens de WhatsApp.</p></div></div><div class="form-grid two"><label>Número principal do WhatsApp<input v-model="form.contact.whatsapp_number" maxlength="30" placeholder="5519999999999" /></label><label>Mensagem padrão<textarea v-model="form.contact.default_message" rows="3" maxlength="1000" placeholder="Olá! Gostaria de saber mais sobre os cursos." /></label></div></section><section class="form-card"><div class="form-card-heading"><div><h2>Links sociais</h2><p>Preencha somente os canais que deseja exibir.</p></div></div><div class="form-grid three"><label>Instagram<input v-model="form.social_links.instagram" placeholder="https://instagram.com/…" /></label><label>YouTube<input v-model="form.social_links.youtube" placeholder="https://youtube.com/…" /></label><label>LinkedIn<input v-model="form.social_links.linkedin" placeholder="https://linkedin.com/…" /></label></div></section><section class="form-card"><div class="form-card-heading"><div><h2>Textos institucionais</h2><p>Textos curtos; sem CNPJ, endereço ou alegações de instituição de ensino.</p></div></div><div class="form-grid"><label>Apresentação curta<textarea v-model="form.institutional.about" rows="3" placeholder="Como o Especializa Condutor apresenta as ofertas parceiras." /></label><label>Texto de rodapé<textarea v-model="form.institutional.footer" rows="2" /></label></div></section><section class="form-card"><button class="form-card-toggle" type="button" :aria-expanded="faqOpen" @click="faqOpen = !faqOpen"><span><strong>Perguntas frequentes globais</strong><small>Usadas na página inicial.</small></span><ChevronUp v-if="faqOpen" :size="19" /><ChevronDown v-else :size="19" /></button><div v-if="faqOpen" class="faq-editor"><div v-for="(faq, index) in form.global_faq" :key="index"><label>Pergunta<input v-model="faq.question" maxlength="255" /></label><label>Resposta<textarea v-model="faq.answer" rows="3" /></label><button type="button" class="text-danger" @click="removeFaq(index)"><Trash2 :size="16" />Remover</button></div><button class="text-button" type="button" @click="addFaq"><Plus :size="16" />Adicionar pergunta</button></div></section><section class="form-card"><div class="form-card-heading"><div><h2>Categorias de cursos</h2><p>Organize o catálogo sem criar novas páginas.</p></div></div><div class="category-create"><input v-model="categoryName" placeholder="Nome da categoria" /><input v-model="categorySlug" placeholder="slug (opcional)" /><button class="admin-button secondary" type="button" @click="addCategory"><Plus :size="17" />Adicionar</button></div><div class="category-list"><div v-for="category in categories" :key="category.id"><span><strong>{{ category.name }}</strong><small>{{ category.courses_count }} curso(s)</small></span><button class="text-danger" type="button" @click="selectedCategory = category"><Trash2 :size="16" />Excluir</button></div></div></section><section class="form-card"><div class="form-card-heading"><div><h2>Cursos em destaque</h2><p>A sequência definida aqui controla a prioridade na página inicial.</p></div></div><div class="featured-select"><label v-for="course in courses" :key="course.id"><input v-model="form.featured_course_ids" type="checkbox" :value="course.id" /><span>{{ course.name }}</span></label></div></section></form><ConfirmModal :open="Boolean(selectedCategory)" title="Excluir esta categoria?" description="Cursos vinculados permanecerão no catálogo, mas sem categoria." confirm-label="Excluir categoria" :busy="deleting" @cancel="selectedCategory = null" @confirm="removeCategory" /></template>
